mapper.select:
select SCHEME_ID as schemeId, SCHEME_NAME as schemeName, SCHEME_DESCRIPTION as schemeDescription, ISDEFAULT as isdefault, CREATE_USER as createUser, CREATE_DEPT as createDept, CREATE_TIME as createTime, UPDATE_USER as updateUser, UPDATE_TIME as updateTime from bok_VAL_SCHEME
AND ( SCHEME_ID like concat_ws('','%',#{searchKey},'%') OR SCHEME_NAME like concat_ws('','%',#{searchKey},'%') )
AND ( SCHEME_ID like concat_ws('','%',#{search},'%') OR SCHEME_NAME like concat_ws('','%',#{search},'%') )
AND (SCHEME_ID = #{schemeId} OR SCHEME_NAME = #{schemeName} )
AND SCHEME_NAME = #{schemeName}
AND SCHEME_ID != #{owner}

select sd.SCHEME_DETAIL_ID as schemeDetailId, sd.SCHEME_ID as schemeId, sd.TRADE_MARKET as tradeMarketCode, sd.TRADE_MARKET as tradeMarket, sd.SEC_TYPE as secTypeCode, sd.SEC_TYPE as secType, sd.SEC_DETAIL_TYPE as secDetailTypeCode, sd.SEC_DETAIL_TYPE as secDetailType, sd.INV_AIM as invAimCode, sd.INV_AIM as invAim, sd.VALUATION_METHOD as valuationMethodCode, sd.VALUATION_METHOD as valuationMethod, sd.VALUATION_PRICE as valuationPriceCode, sd.VALUATION_PRICE as valuationPrice, sd.VALUATION_PRICE_2 as valuationPrice2Code, sd.VALUATION_PRICE_2 as valuationPrice2, sd.QUOTA_DIGIT as quotaDigit, sd.PRICE_TAIL_MODE as priceTailMode, sd.PRICE_TAIL_MODE as priceTailModeCode, sd.PRICE_CLASS as priceClass, sd.PRICE_CLASS as priceClassCode, sd.VALUATION_DATE as valuationDate, sd.VALUATION_DATE as valuationDateCode, DATE_FORMAT(sd.VDATE,'%Y-%m-%d') AS vdate, DATE_FORMAT(sd.MDATE,'%Y-%m-%d') AS mdate,
s.SCHEME_DESCRIPTION as schemeDescription from bok_VAL_SCHEME_DETAIL sd inner join bok_VAL_SCHEME s on sd.SCHEME_ID = s.SCHEME_ID
AND sd.SCHEME_ID = #{schemeId}
AND sd.SEC_TYPE in
#{item}
AND sd.TRADE_MARKET in
#{item}
AND sd.SEC_DETAIL_TYPE in
#{item}
AND sd.INV_AIM in
#{item}
AND sd.SCHEME_DETAIL_ID != #{owner}
AND sd.VDATE = STR_TO_DATE(#{vdate},'%Y-%m-%d')
AND (sd.SCHEME_DETAIL_ID in
null) OR sd.SCHEME_DETAIL_ID in (
#{item}
)
order by sd.update_time desc

select t.SCHEME_DETAIL_ID as schemeDetailId, t.SCHEME_ID as schemeId, IFNULL(vfp.finprod_market_id,t.FINPROD_ID) as finprodId, t.FINPROD_NAME as finprodName, t.TRADE_MARKET as tradeMarketCode, t.TRADE_MARKET as tradeMarket, t.SEC_TYPE as secTypeCode, t.SEC_TYPE as secType, t.SEC_DETAIL_TYPE as secDetailTypeCode, t.SEC_DETAIL_TYPE as secDetailType, t.INV_AIM as invAimCode, t.INV_AIM as invAim, t.VALUATION_METHOD as valuationMethodCode, t.VALUATION_METHOD as valuationMethod, t.VALUATION_PRICE as valuationPriceCode, t.VALUATION_PRICE as valuationPrice, t.VALUATION_PRICE_2 as valuationPrice2Code, t.VALUATION_PRICE_2 as valuationPrice2, t.QUOTA_DIGIT as quotaDigit, t.PRICE_TAIL_MODE as priceTailMode, t.PRICE_TAIL_MODE as priceTailModeCode, t.PRICE_CLASS as priceClass, t.PRICE_CLASS as priceClassCode, t.VALUATION_DATE as valuationDate, t.VALUATION_DATE as valuationDateCode, DATE_FORMAT(t.VDATE,'%Y-%m-%d') AS vdate, DATE_FORMAT(t.MDATE,'%Y-%m-%d') AS mdate from BOK_VAL_SCHEME_DETAIL_SPECIAL t left join FIN_PRODUCT vfp on t.FINPROD_ID = vfp.FINPROD_ID and vfp.FINPROD_TYPE = 'F01'
AND t.SCHEME_ID = #{schemeId}
AND ( t.FINPROD_ID like concat_ws('','%',#{search},'%') OR t.FINPROD_NAME like concat_ws('','%',#{search},'%') )
AND IFNULL(vfp.finprod_market_id,t.FINPROD_ID) in
#{item}
AND t.TRADE_MARKET in
#{item}
AND t.INV_AIM in
#{item}
AND t.SCHEME_DETAIL_ID != #{owner}
AND t.VDATE is not null AND t.MDATE is null
AND t.MDATE >= STR_TO_DATE(#{vdate},'%Y-%m-%d')
AND t.VDATE <= STR_TO_DATE(#{mdate},'%Y-%m-%d') AND t.MDATE is null
AND not(t.VDATE > STR_TO_DATE(#{mdate}, '%Y-%m-%d') OR t.MDATE < STR_TO_DATE(#{vdate}, '%Y-%m-%d'))
AND t.SCHEME_DETAIL_ID in
#{item}
order by t.update_time desc

select distinct FINPROD_ID as finprodId, FINPROD_NAME as finprodName from BOK_VAL_SCHEME_DETAIL_SPECIAL
AND SCHEME_ID = #{schemeId}
AND ( FINPROD_ID like concat_ws('','%',#{search},'%') OR FINPROD_NAME like concat_ws('','%',#{search},'%') )

select distinct sdl.ITEM_CODE id, sdl.ITEM_VALUE text from SYS_DATADICT_LIST sdl inner join SYS_DATADICT_LIST_LINK sdll on sdl.ITEM_CODE = sdll.ITEM_CODE
and sdll.LINKED_DICT_CODE = #{dict_code_parent}
and sdl.DICT_CODE = #{dict_code_child} and sdll.DICT_CODE = #{dict_code_child}
and TRIM(sdll.LINKED_ITEM_CODE) = TRIM(#{item_code_parent})
sdl.ITEM_VALUE like concat_ws('','%',#{search},'%')
order by sdl.ITEM_CODE

select distinct sdl.ITEM_CODE id, sdl.ITEM_VALUE text from SYS_DATADICT_LIST sdl inner join SYS_DATADICT_LIST_LINK sdll on sdl.ITEM_CODE = sdll.ITEM_CODE
and sdll.LINKED_DICT_CODE = #{dict_code_parent}
and sdl.DICT_CODE = #{dict_code_child} and sdll.DICT_CODE = #{dict_code_child}
and TRIM(sdll.LINKED_ITEM_CODE) = TRIM(#{item_code_parent})
sdl.ITEM_VALUE like concat_ws('','%',#{search},'%')
order by sdl.ITEM_CODE
